## Code Example
```javascript
async function routeQuery(tenantId, query){
  const residency = getResidency(tenantId);
  const budget = await getBudget(tenantId);
  const model = (budget.remaining > estimateCost(query) && residency.allowed) ? 'gpt-4o' : 'gpt-3.5-turbo';
  const kb = await fetchKB(tenantId, model);
  const embedding = await ensureEmbedding(tenantId, kb);
  const resp = await callOpenAI(model, query, kb, embedding);
  return resp;
}
```

